def gen(rng):
    def fmt(c):
        return str(len(c)) + '\n' + '\n'.join(f'{a} {b}' for a, b in c)
    tests = [fmt([(1, 1), (1, 1)]), fmt([(10**9, 1), (1, 10**9)]), fmt([(5, 5)] * 4),
             fmt([(1, 2), (1, 2)]), fmt([(2, 1), (2, 1), (2, 1), (2, 1)]),
             fmt([(5, 9), (8, 3), (2, 7), (6, 6)])]
    for m in (2, 4, 6, 8, 10, 12):
        for _ in range(3):
            hi = rng.choice([5, 30, 1000])
            tests.append(fmt([(rng.randint(1, hi), rng.randint(1, hi)) for _ in range(m)]))
    M = 10**5
    tests.append(fmt([(rng.randint(1, 10**9), rng.randint(1, 10**9)) for _ in range(M)]))
    tests.append(fmt([(rng.randint(1, 10**9), rng.randint(1, 10**9)) for _ in range(M)]))
    tests.append(fmt([(10**9, 10**9)] * M))
    tests.append(fmt([(rng.randint(1, 10), rng.randint(1, 10)) for _ in range(M)]))
    return tests

